from functools import lru_cache
class Solution:
    def countSequencesToK(self, nums: List[int], k: int) -> int:
        def factor(x):
            e = [0, 0, 0]
            for i, p in enumerate((2, 3, 5)):
                while x % p == 0:
                    x //= p
                    e[i] += 1
            return e if x == 1 else None
        target = factor(k)
        if target is None:
            return 0
        fs = [factor(x) for x in nums]
        n = len(nums)
        @lru_cache(maxsize=None)
        def go(i, a, b, c):
            if i == n:
                return 1 if (a, b, c) == tuple(target) else 0
            pa, pb, pc = fs[i]
            return (go(i + 1, a + pa, b + pb, c + pc)
                    + go(i + 1, a - pa, b - pb, c - pc)
                    + go(i + 1, a, b, c))
        return go(0, 0, 0, 0)

