class Solution {
    struct E { int a, b, c; };
    bool factor(long long x, E& out) {
        out = {0, 0, 0};
        int ps[3] = {2, 3, 5};
        int* e = &out.a;
        for (int i = 0; i < 3; i++)
            while (x % ps[i] == 0) { x /= ps[i]; e[i]++; }
        return x == 1;
    }
    unordered_map<long long, long long> memo;
    vector<E> fs;
    E target;
    int n;
    long long go(int i, int a, int b, int c) {
        if (i == n) return (a == target.a && b == target.b && c == target.c) ? 1 : 0;
        long long key = ((((long long)i * 50 + a + 25) * 50) + b + 25) * 50 + c + 25;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        E& f = fs[i];
        long long r = go(i + 1, a + f.a, b + f.b, c + f.c)
                    + go(i + 1, a - f.a, b - f.b, c - f.c)
                    + go(i + 1, a, b, c);
        memo[key] = r;
        return r;
    }
public:
    long long countSequencesToK(vector<int>& nums, long long k) {
        if (!factor(k, target)) return 0;
        n = nums.size();
        fs.resize(n);
        for (int i = 0; i < n; i++) factor(nums[i], fs[i]);
        return go(0, 0, 0, 0);
    }
};

