import java.util.*;
class Solution {
    private int[][] fs;
    private int[] target;
    private int n;
    private Map<Long, Long> memo = new HashMap<>();
    private int[] factor(long x) {
        int[] e = new int[3];
        int[] ps = {2, 3, 5};
        for (int i = 0; i < 3; i++)
            while (x % ps[i] == 0) { x /= ps[i]; e[i]++; }
        return x == 1 ? e : null;
    }
    private long go(int i, int a, int b, int c) {
        if (i == n)
            return (a == target[0] && b == target[1] && c == target[2]) ? 1 : 0;
        long key = ((((long) i * 50 + a + 25) * 50) + b + 25) * 50 + c + 25;
        Long cached = memo.get(key);
        if (cached != null) return cached;
        int[] f = fs[i];
        long r = go(i + 1, a + f[0], b + f[1], c + f[2])
               + go(i + 1, a - f[0], b - f[1], c - f[2])
               + go(i + 1, a, b, c);
        memo.put(key, r);
        return r;
    }
    public long countSequencesToK(int[] nums, long k) {
        target = factor(k);
        if (target == null) return 0;
        n = nums.length;
        fs = new int[n][];
        for (int i = 0; i < n; i++) fs[i] = factor(nums[i]);
        return go(0, 0, 0, 0);
    }
}

