from collections import defaultdict
class Solution:
    def countSequencesToK(self, nums: List[int], k: int) -> int:
        def factor(x):
            e = [0, 0, 0]
            for i, p in enumerate((2, 3, 5)):
                while x % p == 0:
                    x //= p
                    e[i] += 1
            return tuple(e) if x == 1 else None
        target = factor(k)
        if target is None:
            return 0
        cur = {(0, 0, 0): 1}
        for x in nums:
            f = factor(x)
            nxt = defaultdict(int)
            for (a, b, c), cnt in cur.items():
                nxt[(a + f[0], b + f[1], c + f[2])] += cnt
                nxt[(a - f[0], b - f[1], c - f[2])] += cnt
                nxt[(a, b, c)] += cnt
            cur = nxt
        return cur.get(target, 0)

