class Solution {
public:
    bool factor(long long x, array<int,3>& e) {
        e = {0,0,0};
        int ps[3] = {2,3,5};
        for (int i = 0; i < 3; i++)
            while (x % ps[i] == 0) { x /= ps[i]; e[i]++; }
        return x == 1;
    }
    long long countSequencesToK(vector<int>& nums, long long k) {
        array<int,3> t;
        if (!factor(k, t)) return 0;
        map<array<int,3>, long long> cur;
        cur[{0,0,0}] = 1;
        for (int x : nums) {
            array<int,3> f;
            factor(x, f);
            map<array<int,3>, long long> nxt;
            for (auto& [st, cnt] : cur) {
                nxt[{st[0]+f[0], st[1]+f[1], st[2]+f[2]}] += cnt;
                nxt[{st[0]-f[0], st[1]-f[1], st[2]-f[2]}] += cnt;
                nxt[st] += cnt;
            }
            cur = move(nxt);
        }
        auto it = cur.find(t);
        return it == cur.end() ? 0 : it->second;
    }
};

