import java.util.*;
class Solution {
    private int[] factor(long x) {
        int[] e = new int[3];
        int[] ps = {2, 3, 5};
        for (int i = 0; i < 3; i++)
            while (x % ps[i] == 0) { x /= ps[i]; e[i]++; }
        return x == 1 ? e : null;
    }
    public long countSequencesToK(int[] nums, long k) {
        int[] t = factor(k);
        if (t == null) return 0;
        Map<Long, Long> cur = new HashMap<>();
        cur.put(pack(0, 0, 0), 1L);
        for (int x : nums) {
            int[] f = factor(x);
            Map<Long, Long> nxt = new HashMap<>();
            for (Map.Entry<Long, Long> en : cur.entrySet()) {
                long key = en.getKey(); long cnt = en.getValue();
                int a = (int)(key / 2500) - 25;
                int b = (int)((key / 50) % 50) - 25;
                int c = (int)(key % 50) - 25;
                nxt.merge(pack(a + f[0], b + f[1], c + f[2]), cnt, Long::sum);
                nxt.merge(pack(a - f[0], b - f[1], c - f[2]), cnt, Long::sum);
                nxt.merge(pack(a, b, c), cnt, Long::sum);
            }
            cur = nxt;
        }
        return cur.getOrDefault(pack(t[0], t[1], t[2]), 0L);
    }
    private long pack(int a, int b, int c) {
        return ((long)(a + 25) * 50 + (b + 25)) * 50 + (c + 25);
    }
}

