    const factor = (x) => {
        const e = [0, 0, 0];
        for (let i = 0; i < 3; i++) {
            const p = [2, 3, 5][i];
            while (x % p === 0) { x /= p; e[i]++; }
        }
        return x === 1 ? e : null;
    };
    const t = factor(Number(k));
    if (t === null) return 0;
    let cur = new Map([["0,0,0", 1]]);
    for (const x of nums) {
        const f = factor(x);
        const nxt = new Map();
        for (const [key, cnt] of cur) {
            const [a, b, c] = key.split(',').map(Number);
            for (const st of [[a+f[0],b+f[1],c+f[2]], [a-f[0],b-f[1],c-f[2]], [a,b,c]]) {
                const nk = st.join(',');
                nxt.set(nk, (nxt.get(nk) || 0) + cnt);
            }
        }
        cur = nxt;
    }
    return cur.get(t.join(',')) || 0;
};
